503: function setJoystick(e) {
504:   if (!game || !joystick || !joystickKnob) return;
505:   const rect = joystick.getBoundingClientRect();
506:   const cx = rect.left + rect.width / 2;
507:   const cy = rect.top + rect.height / 2;
508:   let dx = e.clientX - cx;
509:   let dy = e.clientY - cy;
510:   const max = rect.width * 0.36;
511:   const len = Math.hypot(dx, dy) || 1;
512:   if (len > max) { dx = dx / len * max; dy = dy / len * max; }
513:   joystickKnob.style.transform = `translate(${dx}px, ${dy}px)`;
514: 
515:   const nx = dx / max, ny = dy / max;
516:   const dead = 0.2;
517:   const inp = game.input;
518:   inp.left = nx < -dead;
519:   inp.right = nx > dead;
520:   inp.up = ny < -dead;
521:   inp.down = ny > dead;
522: }
