422:   // ================= SOBREVIVÊNCIA =================
423:   updateSurvival(dt) {
424:     const p = this.player;
425:     if (p.downed) return;
426:     if (p.inVehicle) return;
427:     const d = this.diff;
428:     p.hunger = clamp(p.hunger - 0.020 * dt * d.hunger, 0, 100);
429:     p.thirst = clamp(p.thirst - 0.029 * dt * d.hunger, 0, 100);
430:     p.fatigue = clamp(p.fatigue + 0.011 * dt * (isNight(this.time) ? 1.4 : 1) * 0.8, 0, 100);
431:     p.hygiene = clamp(p.hygiene - 0.0035 * dt, 0, 100);
432:     p.stamina = clamp(p.stamina, 0, p.maxStamina);
433: 
434:     // Sangramento
435:     if (p.bleed > 0) {
436:       p.health -= 0.45 * (p.bleed / 100) * dt;
437:       p.bleed = Math.max(0, p.bleed - 0.22 * dt);
438:     }
439:     // Infecção
440:     if (p.infection > 0) {
441:       p.infection = clamp(p.infection + 0.0045 * dt * d.infect, 0, 100);
442:       if (p.infection > 55) p.health -= 0.09 * (p.infection / 100) * dt;
443:       if (p.infection > 60 && !p.infectionWarned) {
444:         p.infectionWarned = true;
445:         this.ui?.notify('Febre e calafrios. A infecção está avançando. Antibióticos podem salvar você.', 'danger', '🦠');
446:       }
447:     }
448:     if (p.sick > 0) {
449:       p.sick = Math.max(0, p.sick - 0.01 * dt);
450:       p.health -= 0.025 * (p.sick / 100) * dt;
451:     }
452:     // Necessidades críticas
453:     if (p.hunger <= 0) p.health -= 0.05 * dt;
454:     if (p.thirst <= 0) p.health -= 0.09 * dt;
455:     if (p.fatigue > 90) { p.stamina = Math.min(p.stamina, 35); p.health -= 0.015 * dt; }
456: 
457:     // Temperatura
458:     const season = SEASONS[this.seasonIndex];
459:     let target = 36.8 + season.temp * 0.012;
460:     if (isNight(this.time)) target -= 0.35;
461:     target -= (p.wet / 100) * 1.25;
462:     if (this.weather === 'chuva' || this.weather === 'tempestade') target -= 0.25;
463:     let insulation = 0;
464:     for (const s of this.clothingStacks) insulation += ITEMS[s.id].insulation || 0;
465:     target += insulation * 0.13;
466:     let nearFire = false;
467:     for (const st of this.world.structures) {
468:       if (st.type === 'fogueira' && dist(p.x, p.y, st.x * TILE + 16, st.y * TILE + 16) < 130) nearFire = true;
469:     }
470:     if (nearFire) target += 0.9;
471:     if (this.world.buildingAt(p.x, p.y)) target += 0.2;
472:     p.temp += (target - p.temp) * Math.min(1, dt / 22);
473:     if (p.temp < 36.1) p.health -= (36.1 - p.temp) * 0.22 * dt;
474:     if (p.temp > 38.6) p.health -= (p.temp - 38.6) * 0.16 * dt;
475: 
476:     // Molhado / secagem
477:     const wdef = WEATHERS[this.weather] || WEATHERS.limpo;
478:     const rainproof = this.clothingStacks.some(s => ITEMS[s.id].rainproof);
479:     if (wdef.wet > 0 && !rainproof && !this.world.buildingAt(p.x, p.y)) p.wet = clamp(p.wet + wdef.wet * 4.5 * dt, 0, 100);
480:     else p.wet = clamp(p.wet - 1.6 * dt * (nearFire ? 3.5 : 1), 0, 100);
481: 
482:     // Regeneração
483:     if (p.bleed <= 0 && p.infection < 20 && p.hunger > 28 && p.thirst > 28 && p.fatigue < 85 && p.health < p.maxHealth) {
484:       p.health += 0.035 * dt;
485:     }
486:     // Ferimentos
487:     for (const k of ['leg', 'arm']) {
488:       if (p.injuries[k] > 0) p.injuries[k] = Math.max(0, p.injuries[k] - 0.0015 * dt);
489:     }
490:     p.health = clamp(p.health, 0, p.maxHealth);
491:     // Avisos de estado
492:     if (this.clock - p.lastStatus > 30) {
493:       p.lastStatus = this.clock;
494:       if (p.hunger < 18) this.ui?.notify('Sua barriga ronca. Você precisa comer.', 'warn', '🍖');
495:       else if (p.thirst < 18) this.ui?.notify('Sua garganta está seca. Beba algo.', 'warn', '💧');
496:       else if (p.fatigue > 82) this.ui?.notify('O cansaço pesa. Durma em uma cama.', 'warn', '😴');
497:       else if (p.temp < 36.0) this.ui?.notify('Você está com hipotermia. Procure calor e roupa seca.', 'danger', '🥶');
498:       else if (p.infection > 35) this.ui?.notify('A infecção está se espalhando. Use antibióticos.', 'danger', '🦠');
499:     }
500:     if (p.health <= 0) this.killPlayer(this.deathReason());
501:     // Sincroniza barra
502:     if (this.ui) this.ui.hudDirty = true;
503:   }
