505:   deathReason() {
506:     const p = this.player;
507:     if (p.bleed > 25) return 'perdeu sangue demais';
508:     if (p.infection > 55) return 'não resistiu à infecção';
509:     if (p.thirst <= 0) return 'morreu de sede';
510:     if (p.hunger <= 0) return 'morreu de fome';
511:     if (p.temp < 35.7) return 'morreu de hipotermia';
512:     return 'não resistiu aos ferimentos';
