533:   damagePlayer(amount, source = 'zumbi', opts = {}) {
534:     const p = this.player;
535:     if (this.dead || p.downed) return;
536:     let armor = 0;
537:     for (const s of this.clothingStacks) armor += ITEMS[s.id].armor || 0;
538:     const reduced = Math.max(1, amount - armor * 0.75);
539:     p.health -= reduced;
540:     p.lastHurt = this.clock;
541:     this.hurtFlash = Math.min(1, this.hurtFlash + 0.55);
542:     this.shake = Math.min(12, this.shake + 4);
543:     audio.play('hurt');
544:     this.addFloater(p.x, p.y - 22, `-${Math.round(reduced)}`, '#ff6b63', 1.1);
545:     if (source === 'zumbi') {
546:       if (chance(this.world.rng, 0.33 * this.diff.infect)) {
547:         p.bleed = clamp(p.bleed + randRange(this.world.rng, 12, 30), 0, 100);
548:         this.ui?.notify('Você está sangrando. Use uma bandagem.', 'danger', '🩸');
549:       }
550:       if (chance(this.world.rng, 0.18 * this.diff.infect)) {
551:         p.infection = clamp(p.infection + randRange(this.world.rng, 5, 13), 0, 100);
552:       }
553:       if (chance(this.world.rng, 0.055)) {
554:         const leg = chance(this.world.rng, 0.5);
555:         p.injuries[leg ? 'leg' : 'arm'] = Math.min(1, p.injuries[leg ? 'leg' : 'arm'] + 0.35);
556:         this.ui?.notify(leg ? 'Ferimento na perna. Você está mais lento.' : 'Ferimento no braço. Seus golpes perderam força.', 'danger', '🦴');
557:       }
558:     }
559:     p.health = clamp(p.health, 0, p.maxHealth);
560:     if (p.health <= 0) this.killPlayer(source === 'fome' ? 'morreu de fome' : 'foi morto por zumbis');
561:     if (this.ui) this.ui.hudDirty = true;
562:   }
