569:   // ================= MOVIMENTO =================
570:   updatePlayer(dt) {
571:     const p = this.player;
572:     const inp = this.input;
573:     if (p.downed) {
574:       p.downTimer -= dt;
575:       if (p.downTimer <= 0) this.reviveSelf();
576:       return;
577:     }
578:     if (p.inVehicle) {
579:       p.x = p.inVehicle.x; p.y = p.inVehicle.y; p.angle = p.inVehicle.angle;
580:       return;
581:     }
582:     // mira
583:     if (inp.pointerActive) {
584:       const z = this.camera.zoom || 1;
585:       const wx = this.camera.x + inp.pointerX / z, wy = this.camera.y + inp.pointerY / z;
586:       p.angle = angleTo(p.x, p.y, wx, wy);
587:       this.aim.x = wx; this.aim.y = wy; this.aim.active = true;
588:     } else if (inp.touchAim) {
589:       p.angle = angleTo(p.x, p.y, inp.touchAim.x, inp.touchAim.y);
590:       this.aim.x = inp.touchAim.x; this.aim.y = inp.touchAim.y; this.aim.active = true;
591:     } else {
592:       const nearest = this.nearestZombie(p.x, p.y, 380);
593:       if (nearest) { p.angle = angleTo(p.x, p.y, nearest.x, nearest.y); this.aim.x = nearest.x; this.aim.y = nearest.y; this.aim.active = true; }
594:       else this.aim.active = false;
595:     }
596:     let dx = (inp.right ? 1 : 0) - (inp.left ? 1 : 0);
597:     let dy = (inp.down ? 1 : 0) - (inp.up ? 1 : 0);
598:     const len = Math.hypot(dx, dy);
599:     let moving = len > 0;
600:     if (moving) { dx /= len; dy /= len; }
601:     p.sprinting = inp.sprint && moving && p.stamina > 3;
602:     let speed = 138 * (1 + (p.skills.condicionamento.level || 0) * 0.018);
603:     if (p.sprinting) speed *= 1.48;
604:     else if (inp.sneak) speed *= 0.46;
605:     if (p.injuries.leg > 0) speed *= 1 - p.injuries.leg * 0.32;
606:     if (this.weight() > this.capacity()) speed *= 0.62;
607:     if (p.fatigue > 85) speed *= 0.85;
608:     if (p.health < 30) speed *= 0.85;
609:     if (p.hunger < 10 || p.thirst < 10) speed *= 0.9;
610:     if (moving) {
611:       const ox = p.x, oy = p.y;
612:       this.moveEntity(p, dx * speed * dt, dy * speed * dt, 10);
613:       const moved = dist(ox, oy, p.x, p.y);
614:       this.stats.distance += moved;
615:       p.footstep -= dt;
616:       if (p.footstep <= 0) {
617:         const noiseR = inp.sneak ? 26 : p.sprinting ? 145 : 62;
618:         this.emitNoise(p.x, p.y, noiseR, 'passos');
619:         p.footstep = p.sprinting ? 0.34 : inp.sneak ? 0.8 : 0.52;
620:       }
621:     }
622:     if (p.sprinting) {
623:       p.stamina -= 15 * dt;
624:       p.fatigue += 0.008 * dt;
625:     } else {
626:       p.stamina += (8.5 + (p.skills.condicionamento.level || 0) * 0.7) * dt;
627:     }
628:     p.stamina = clamp(p.stamina, 0, p.maxStamina);
629:     p.attackCd = Math.max(0, p.attackCd - dt);
630:     p.swing = Math.max(0, p.swing - dt * 3.4);
631:     if (inp.attack && p.attackCd <= 0) this.attack();
632:     this.revealTimer -= dt;
633:     if (this.revealTimer <= 0) {
634:       this.revealTimer = 0.35;
635:       this.world.reveal(Math.floor(p.x / TILE), Math.floor(p.y / TILE), 9);
636:     }
637:   }
