639:   moveEntity(e, dx, dy, r) {
640:     if (!this.world.collidesCircle(e.x + dx, e.y, r)) e.x += dx;
641:     else e.blocked = true;
642:     if (!this.world.collidesCircle(e.x, e.y + dy, r)) e.y += dy;
643:     else e.blocked = true;
644:     e.x = clamp(e.x, r, this.world.w * TILE - r);
645:     e.y = clamp(e.y, r, this.world.h * TILE - r);
646:   }
