652:   nearestZombie(x, y, radius = 1e9) {
653:     let best = null, bd = radius * radius;
654:     for (const z of this.zombies) {
655:       if (z.dead) continue;
656:       const d = (z.x - x) ** 2 + (z.y - y) ** 2;
657:       if (d < bd) { bd = d; best = z; }
658:     }
659:     return best;
660:   }
661: 
662:   nearestHostileNPC(x, y, radius = 1e9) {
663:     let best = null, bd = radius * radius;
664:     for (const n of this.npcs) {
665:       if (!n.alive || !n.hostile) continue;
666:       const d = (n.x - x) ** 2 + (n.y - y) ** 2;
667:       if (d < bd) { bd = d; best = n; }
668:     }
669:     return best;
670:   }
