673:   getQuickSlots() {
674:     const inv = this.player.inventory;
675:     const usable = inv.filter(s => ['food', 'drink', 'med', 'hygiene', 'misc'].includes(ITEMS[s.id]?.type) && ITEMS[s.id].type !== 'valuable');
676:     const p = this.player;
677:     const score = s => {
678:       const d = ITEMS[s.id];
679:       let v = 0;
680:       if (p.thirst < 55 && (d.thirst || 0) > 0) v += (60 - p.thirst) + (d.thirst || 0);
681:       if (p.hunger < 55 && (d.hunger || 0) > 0) v += (60 - p.hunger) + (d.hunger || 0);
682:       if (p.bleed > 0 && d.bleed) v += 300;
683:       if (p.infection > 10 && d.infection) v += 200;
684:       if (p.health < 60 && d.heal) v += (100 - p.health);
685:       v += (d.value || 0) * 0.05;
686:       return v;
687:     };
688:     return usable.sort((a, b) => score(b) - score(a)).slice(0, 4);
689:   }
