698:   useItem(stack) {
699:     const def = ITEMS[stack.id];
700:     if (!def || this.dead) return false;
701:     const p = this.player;
702:     if (def.type === 'med') {
703:       const skill = p.skills.primeiros_socorros.level || 0;
704:       const mult = 1 + skill * 0.07;
705:       let did = false;
706:       if (def.bleed && p.bleed > 0) { p.bleed = clamp(p.bleed + def.bleed * 100, 0, 100); did = true; }
707:       if (def.heal) { this.healPlayer(def.heal * mult); did = true; }
708:       if (def.infection) { p.infection = clamp(p.infection + def.infection * mult, 0, 100); did = true; }
709:       if (def.fever) { p.temp = lerp(p.temp, 36.8, 0.4); did = true; }
710:       if (def.fatigue) p.fatigue = clamp(p.fatigue + def.fatigue, 0, 100);
711:       if (!did && p.health >= p.maxHealth) { this.ui?.notify('Você não precisa disso agora.', 'info', def.icon); return false; }
712:       this.grantSkill('primeiros_socorros', def.type === 'med' ? 4 : 1);
713:       audio.play('heal');
714:       this.spendGameMinutes(4);
715:       this.addFloater(p.x, p.y - 26, def.name, '#8be28b', 1.2);
716:       this.consumeStack(stack, 1);
717:       return true;
718:     }
719:     if (def.type === 'food' || def.type === 'drink') {
720:       if (def.cooked) {
721:         // cru: pode comer, mas é arriscado
722:       }
723:       p.hunger = clamp(p.hunger + (def.hunger || 0) * (def.type === 'food' && (p.skills.culinaria.level || 0) > 0 ? 1 + p.skills.culinaria.level * 0.02 : 1), 0, 100);
724:       p.thirst = clamp(p.thirst + (def.thirst || 0), 0, 100);
725:       if (def.fatigue) p.fatigue = clamp(p.fatigue + def.fatigue, 0, 100);
726:       if (def.health) p.health = clamp(p.health + def.health, 0, p.maxHealth);
727:       if (def.morale) p.fatigue = clamp(p.fatigue - def.morale * 0.15, 0, 100);
728:       if (def.sickChance && chance(this.world.rng, def.sickChance * (1 - (p.skills.culinaria.level || 0) * 0.02))) {
729:         p.sick = clamp(p.sick + randRange(this.world.rng, 22, 42), 0, 100);
730:         this.ui?.notify('Seu estômago revira. Você não devia ter comido isso.', 'danger', '🤢');
731:       }
732:       this.completeObjective(def.type === 'drink' ? 'drink' : 'eat');
733:       audio.play(def.type === 'drink' ? 'drink' : 'eat');
734:       this.spendGameMinutes(def.type === 'food' ? 3 : 1);
735:       this.addFloater(p.x, p.y - 26, `+${def.type === 'food' ? def.hunger : def.thirst}`, def.type === 'food' ? '#e5c06a' : '#74b9e8', 1.1);
736:       this.consumeStack(stack, 1);
737:       return true;
738:     }
739:     if (def.type === 'hygiene') {
740:       p.hygiene = clamp(p.hygiene + (def.hygiene || 25), 0, 100);
741:       this.spendGameMinutes(6);
742:       this.ui?.notify('Você se limpou um pouco. A vida parece menos miserável.', 'good', '🧼');
743:       this.consumeStack(stack, 1);
744:       return true;
745:     }
746:     if (def.type === 'misc' || def.type === 'valuable') {
747:       if (def.morale) { p.fatigue = clamp(p.fatigue - def.morale, 0, 100); this.ui?.notify('Um pequeno alívio em meio ao caos.', 'good', def.icon); this.consumeStack(stack, 1); this.spendGameMinutes(2); return true; }
748:       if (def.heal) { this.healPlayer(def.heal); this.consumeStack(stack, 1); return true; }
749:       this.ui?.notify(def.desc, 'info', def.icon);
750:       return false;
751:     }
752:     if (def.type === 'seed') {
753:       this.ui?.notify('Plante em um canteiro construído (tecla B).', 'info', '🌱');
754:       return false;
755:     }
756:     this.ui?.notify(`${def.name}: ${def.desc}`, 'info', def.icon);
757:     return false;
758:   }
