785:       this.ui?.notify(`${def.name} ${stack.equipped ? 'vestida' : 'removida'}.`, 'good', def.icon);
786:     } else if (def.type === 'tool' || def.type === 'misc') {
787:       this.ui?.notify(def.desc, 'info', def.icon);
788:     } else if (def.type === 'weapon') {
789:       this.equipItem(stack, slot);
790:     }
791:     if (this.ui) { this.ui.hudDirty = true; this.ui.refreshInventory?.(); }
