824:   // ================= SKILLS =================
825:   grantSkill(skill, amount) {
826:     const s = this.player.skills[skill];
827:     if (!s) return;
828:     const mult = 1 + (this.player.xpBonus || 0);
829:     s.xp += amount * mult;
