247:     const i = this.zombies.indexOf(z);
248:     if (i >= 0) this.zombies.splice(i, 1);
249:     this.corpses.push({ x: z.x, y: z.y, angle: z.angle, type: z.type, size: z.size, time: 0 });
250:     this.stats.kills++;
251:     this.player.kills++;
252:     this.addXP(z.xp || 10);
253:     this.grantSkill('combate', (z.xp || 10) * 0.9);
254:     this.blood(z.x, z.y, z.angle, 16);
255:     audio.play('zombie_die');
256:     if (this.mp?.isHost) this.mp.send({ t: 'zombieDied', zid: z.id });
257:     // saque
258:     if (chance(this.world.rng, 0.38)) {
259:       const bag = this.world.rollLoot('caixa', 0.5);
260:       for (const it of bag) this.groundItems.push({ id: uid('gi'), x: z.x + randRange(this.world.rng, -12, 12), y: z.y + randRange(this.world.rng, -12, 12), stack: it });
261:     }
262:     if (this.ui) this.ui.hudDirty = true;
