288: 
289:   // ================== ZUMBIS ==================
290:   updateZombies(dt) {
291:     if (this.mp && !this.isHost) return this.clientZombieContact(dt);
292:     const p = this.player;
293:     for (const z of [...this.zombies]) {
294:       if (z.dead) continue;
295:       z.anim += dt * (z.state === 'chase' ? 3.2 : 1.4);
296:       z.hitFlash = Math.max(0, z.hitFlash - dt * 3.5);
297:       z.attackCd = Math.max(0, z.attackCd - dt);
298:       z.trapCd = Math.max(0, z.trapCd - dt);
299:       z.blockCd = Math.max(0, (z.blockCd || 0) - dt);
300:       z.groanCd -= dt;
301:       if (z.groanCd <= 0) {
302:         z.groanCd = randRange(this.world.rng, 5, 16);
303:         if (dist(z.x, z.y, p.x, p.y) < 700) audio.play('zombie');
304:       }
305:       z.senseCd = (z.senseCd || 0) - dt;
306:       z.lastX = z.x; z.lastY = z.y;
307:       const target = this.zombieTarget(z);
308:       if (z.senseCd <= 0) {
309:         z.senseCd = 0.22 + Math.random() * 0.14;
310:         const detected = this.zombieDetect(z, target);
311:         if (detected) { z.alert = 7; z.target = { x: target.x, y: target.y }; z.state = 'chase'; }
312:       }
313:       if (z.alert > 0) z.alert -= dt;
314:       if (z.target && z.alert > 0 && target) {
315:         // atualiza posição do alvo enquanto persegue
316:         z.target.x = target.x; z.target.y = target.y;
317:         z.state = dist(z.x, z.y, target.x, target.y) < 34 + z.size * 10 ? 'attack' : 'chase';
318:       } else if (z.alert <= 0) {
319:         z.target = null;
320:         if (z.state === 'chase' || z.state === 'investigate') z.state = 'idle';
321:       }
322: 
323:       let moved = false;
324:       if (z.target && z.alert > 0) {
325:         const d = dist(z.x, z.y, z.target.x, z.target.y);
326:         if (d > 24 + z.size * 8 && z.state !== 'attack') {
327:           const a = angleTo(z.x, z.y, z.target.x, z.target.y);
328:           z.angle = a;
329:           const speed = z.speed * (z.state === 'chase' ? 1 : 0.72);
330:           const before = { x: z.x, y: z.y };
331:           this.moveEntity(z, Math.cos(a) * speed * dt, Math.sin(a) * speed * dt, 9 * z.size);
332:           moved = dist(before.x, before.y, z.x, z.y) > speed * dt * 0.25;
333:         }
334:         if (d < 44 + z.size * 8 && target) {
335:           if (target.kind === 'player' && z.attackCd <= 0) {
336:             this.zombieAttackPlayer(z);
337:           } else if (target.kind === 'npc' && z.attackCd <= 0) {
338:             this.damageNPC(target.ref, z.damage * 0.8, 'zumbi');
339:             z.attackCd = 1.2;
340:             z.lunge = 1;
341:           } else if (target.kind === 'remote' && z.attackCd <= 0) {
342:             this.mp?.send({ t: 'zombieHit', target: target.ref.id, dmg: z.damage });
343:             z.attackCd = 1.2;
344:           }
345:         }
346:       } else {
347:         // vagar
348:         z.idleTimer -= dt;
349:         if (z.idleTimer <= 0) {
350:           z.idleTimer = randRange(this.world.rng, 2, 8);
351:           if (chance(this.world.rng, 0.55)) {
352:             z.wander = {
353:               x: z.home.x + randRange(this.world.rng, -230, 230),
354:               y: z.home.y + randRange(this.world.rng, -230, 230),
355:             };
356:           } else z.wander = null;
357:         }
358:         if (z.wander) {
359:           const d = dist(z.x, z.y, z.wander.x, z.wander.y);
360:           if (d < 14) z.wander = null;
361:           else {
362:             const a = angleTo(z.x, z.y, z.wander.x, z.wander.y);
363:             z.angle = a;
364:             const before = { x: z.x, y: z.y };
365:             this.moveEntity(z, Math.cos(a) * z.speed * 0.38 * dt, Math.sin(a) * z.speed * 0.38 * dt, 9 * z.size);
366:             moved = dist(before.x, before.y, z.x, z.y) > z.speed * 0.38 * dt * 0.25;
367:             if (!moved) z.wander = null;
368:           }
369:         }
370:       }
371:       // obstáculo à frente: atacar porta, janela, barricada ou parede
372:       if (!moved && z.target && z.alert > 0) {
373:         z.stuck = (z.stuck || 0) + dt;
374:         if (z.stuck > 0.25 && z.blockCd <= 0) {
375:           if (this.zombieAttackBlocker(z)) z.stuck = 0;
376:           z.blockCd = 0.8;
377:         }
378:       } else z.stuck = 0;
379:       z.lunge = Math.max(0, (z.lunge || 0) - dt * 4);
380:       // armadilhas
381:       if (z.trapCd <= 0) {
382:         for (const s of this.world.structures) {
383:           if (s.type !== 'armadilha' || s.hp <= 0) continue;
384:           if (dist(z.x, z.y, s.x * TILE + 16, s.y * TILE + 16) < 26) {
385:             this.damageZombie(z, 48, { angle: z.angle });
386:             s.hp -= 18;
387:             z.trapCd = 2;
388:             audio.play('hit');
389:             if (s.hp <= 0) this.destroyStructure(s, false);
390:             break;
391:           }
392:         }
393:       }
394:       // luz / fogo
395:       if (dist(z.x, z.y, p.x, p.y) < 34 && !p.inVehicle && z.attackCd <= 0 && z.state === 'chase') this.zombieAttackPlayer(z);
396:     }
397: 
398:     // separação entre zumbis (evita pilha)
399:     const alive = this.zombies;
400:     for (let i = 0; i < alive.length; i++) {
401:       const a = alive[i];
402:       for (let j = i + 1; j < alive.length; j++) {
403:         const b = alive[j];
404:         const dx = b.x - a.x, dy = b.y - a.y;
405:         const d2 = dx * dx + dy * dy;
406:         const min = 17 * (a.size + b.size);
407:         if (d2 > 0.1 && d2 < min * min) {
408:           const d = Math.sqrt(d2);
409:           const push = (min - d) * 0.5;
410:           const nx = dx / d, ny = dy / d;
411:           a.x -= nx * push; a.y -= ny * push;
412:           b.x += nx * push; b.y += ny * push;
413:         }
414:       }
415:     }
416:   },
417: 
418:   clientZombieContact(dt) {
419:     // O anfitrião é autoritativo para o dano. O cliente apenas anima os zumbis
420:     // sincronizados e deixa os ataques chegarem por "zombieHit".
421:     for (const z of this.zombies) {
422:       if (z.dead) continue;
423:       z.anim = (z.anim || 0) + dt * (z.state === 'chase' ? 3.2 : 1.4);
424:       z.hitFlash = Math.max(0, z.hitFlash - dt * 3.5);
425:       z.attackCd = Math.max(0, (z.attackCd || 0) - dt);
426:     }
427:   },
428: 
429:   zombieTarget(z) {
430:     const p = this.player;
431:     let best = null, bd = 1e9;
432:     if (!p.dead && !p.downed) { best = { kind: 'player', ref: p, x: p.x, y: p.y }; bd = dist(z.x, z.y, p.x, p.y); }
433:     for (const rp of this.remotePlayers.values()) {
434:       if (rp.downed) continue;
435:       const d = dist(z.x, z.y, rp.x, rp.y);
436:       if (d < bd) { bd = d; best = { kind: 'remote', ref: rp, x: rp.x, y: rp.y }; }
437:     }
438:     for (const n of this.npcs) {
439:       if (!n.alive) continue;
440:       const d = dist(z.x, z.y, n.x, n.y);
441:       if (d < bd && d < 900) { bd = d; best = { kind: 'npc', ref: n, x: n.x, y: n.y }; }
442:     }
443:     return best;
444:   },
445: 
446:   zombieDetect(z, target) {
447:     if (!target) return false;
448:     const p = this.player;
449:     const d = dist(z.x, z.y, target.x, target.y);
450:     const vision = (WEATHERS[this.weather] || WEATHERS.limpo).vision;
451:     let sight = (ZOMBIE_TYPES[z.type]?.sight || 220) * vision;
452:     if (target.kind === 'player') {
453:       if (p.flashlight) sight *= 1.35;
454:       if (this.input.sneak) sight *= 0.62;
455:       if (p.inVehicle) sight = Math.max(sight, 500);
456:     }
457:     if (d > sight) return false;
458:     if (d > 75) {
459:       const angleToTarget = angleTo(z.x, z.y, target.x, target.y);
460:       if (Math.abs(angleDiff(z.angle, angleToTarget)) > 1.15) return false;
461:     }
462:     if (!this.world.lineOfSight(z.x, z.y, target.x, target.y)) return false;
463:     return true;
464:   },
465: 
466:   zombieAttackPlayer(z) {
467:     const p = this.player;
468:     z.attackCd = randRange(this.world.rng, 0.9, 1.35);
469:     z.lunge = 1;
470:     audio.play('zombie');
471:     if (p.inVehicle) {
472:       const v = p.inVehicle;
473:       v.condition = Math.max(0, v.condition - z.damage * 0.35);
474:       v.speed *= 0.7;
475:       this.ui?.notify('Zumbis estão batendo no veículo!', 'warn', '🚗');
476:       return;
477:     }
478:     this.damagePlayer(z.damage * randRange(this.world.rng, 0.85, 1.15), 'zumbi');
479:     const knock = 16;
480:     this.moveEntity(p, Math.cos(z.angle) * knock, Math.sin(z.angle) * knock, 10);
481:   },
482: 
483:   zombieAttackBlocker(z) {
484:     // encontra porta, janela ou estrutura na frente imediata
485:     let blocker = null, bd = 56;
486:     for (const d of this.world.doors.values()) {
487:       const px = d.x * TILE + 16, py = d.y * TILE + 16;
488:       const dd = dist(z.x, z.y, px, py);
489:       if (dd < bd) {
490:         const a = angleTo(z.x, z.y, px, py);
491:         if (Math.abs(angleDiff(z.angle, a)) < 1.2) { bd = dd; blocker = { kind: 'door', ref: d, x: px, y: py }; }
492:       }
493:     }
494:     for (const w of this.world.windows.values()) {
495:       const px = w.x * TILE + 16, py = w.y * TILE + 16;
496:       const dd = dist(z.x, z.y, px, py);
497:       if (dd < bd) {
498:         const a = angleTo(z.x, z.y, px, py);
499:         if (Math.abs(angleDiff(z.angle, a)) < 1.2) { bd = dd; blocker = { kind: 'window', ref: w, x: px, y: py }; }
500:       }
501:     }
502:     for (const s of this.world.structures) {
503:       if (!['parede', 'muro_metal', 'cerca', 'barricada', 'reforco_metal'].includes(s.type)) continue;
504:       if (s.portal) continue;
505:       const px = s.x * TILE + 16, py = s.y * TILE + 16;
506:       const dd = dist(z.x, z.y, px, py);
507:       if (dd < bd) {
508:         const a = angleTo(z.x, z.y, px, py);
509:         if (Math.abs(angleDiff(z.angle, a)) < 1.2) { bd = dd; blocker = { kind: 'structure', ref: s, x: px, y: py }; }
510:       }
511:     }
512:     // barricadas em portais primeiro
513:     for (const s of this.world.structures) {
514:       if (!s.portal) continue;
515:       const px = s.x * TILE + 16, py = s.y * TILE + 16;
516:       const dd = dist(z.x, z.y, px, py);
517:       if (dd < 62) { blocker = { kind: 'structure', ref: s, x: px, y: py }; break; }
518:     }
519:     if (!blocker) return false;
520:     if (Math.abs(angleDiff(z.angle, angleTo(z.x, z.y, blocker.x, blocker.y))) > 1.4) return false;
521:     this.damageBlocker(z, blocker);
522:     return true;
523:   },
524: 
525:   damageBlocker(z, blocker) {
526:     const dmg = 15 + z.damage * 0.9;
527:     z.lunge = 1;
528:     if (blocker.kind === 'structure') {
529:       const s = blocker.ref;
530:       s.hp -= dmg;
531:       this.burst(blocker.x, blocker.y, '#8b6f4e', 4, 40);
532:       audio.play('hit');
533:       if (s.hp <= 0) {
534:         this.destroyStructure(s, true);
535:         this.ui?.notify('Uma barreira foi destruída!', 'danger', '🧱');
536:         audio.play('door_break');
537:       }
538:     } else if (blocker.kind === 'door') {
539:       const d = blocker.ref;
540:       if (this.world.portalStructures.has(d.x + ',' + d.y)) return;
541:       d.hp -= dmg;
542:       audio.play('hit');
543:       this.burst(blocker.x, blocker.y, '#7a5b3c', 3, 30);
544:       if (d.hp <= 0) {
545:         d.open = true; d.broken = true;
546:         audio.play('door_break');
547:         this.ui?.notify('Uma porta cedeu à horda.', 'danger', '🚪');
548:       }
549:     } else if (blocker.kind === 'window') {
550:       const w = blocker.ref;
551:       if (this.world.portalStructures.has(w.x + ',' + w.y)) return;
552:       w.hp -= dmg;
553:       audio.play('hit');
554:       this.burst(blocker.x, blocker.y, '#9bb6be', 4, 40);
555:       if (w.hp <= 0) {
556:         w.broken = true;
557:         audio.play('door_break');
558:         this.ui?.notify('Uma janela foi quebrada.', 'warn', '🪟');
559:       }
560:     }
561:   },
562: 
563:   // ================== VEÍCULOS ==================
564:   updateVehicles(dt) {
565:     for (const v of this.world.vehicles) {
566:       if (!v.occupied) continue;
567:       const inp = this.input;
568:       let throttle = (inp.up ? 1 : 0) - (inp.down ? 1 : 0);
569:       const steer = (inp.right ? 1 : 0) - (inp.left ? 1 : 0);
570:       const engineOk = v.fuel > 0 && v.condition > 0;
571:       if (!engineOk) throttle = 0;
572:       v.engineOn = engineOk;
573:       if (!v.engineOn) v.speed *= Math.max(0, 1 - dt * 1.4);
574:       if (v.engineOn) {
575:         if (throttle > 0) v.speed += 130 * dt;
576:         else if (throttle < 0) v.speed -= (v.speed > 0 ? 220 : 110) * dt;
577:         else v.speed *= Math.max(0, 1 - dt * 0.8);
578:         v.speed = clamp(v.speed, -80, 245);
579:         v.fuel = Math.max(0, v.fuel - Math.abs(v.speed) * 0.00016 * dt);
580:         const steerFactor = clamp(Math.abs(v.speed) / 80, 0, 1);
581:         v.angle += steer * 2.1 * dt * steerFactor * (v.speed < 0 ? -1 : 1);
582:       } else {
583:         v.speed *= Math.max(0, 1 - dt * 2);
584:         if (v.fuel <= 0 && v.engineOn === false && inp.up) {
585:           if (!v.emptyWarned) { v.emptyWarned = true; this.ui?.notify('O tanque está vazio. Encontre combustível.', 'warn', '⛽'); }
586:         }
587:       }
588:       const dx = Math.cos(v.angle) * v.speed * dt;
589:       const dy = Math.sin(v.angle) * v.speed * dt;
590:       const nx = v.x + dx, ny = v.y + dy;
591:       const hit = this.world.collidesCircle(nx + Math.cos(v.angle) * v.w * 0.35, ny + Math.sin(v.angle) * v.w * 0.35, 12, v);
592:       if (hit) {
593:         if (Math.abs(v.speed) > 40) {
594:           audio.play('car_hit');
595:           this.shake = Math.min(14, this.shake + Math.abs(v.speed) * 0.05);
596:           v.condition = Math.max(0, v.condition - Math.abs(v.speed) * 0.022);
597:           this.burst(nx, ny, '#c9b88a', 8, 80);
598:           this.ui?.notify(Math.abs(v.speed) > 150 ? 'Batida forte! O veículo sofreu danos.' : 'Você raspou em algo.', 'warn', '💥');
599:           if (v.condition <= 0) this.ui?.notify('O motor morreu. O veículo está inutilizado.', 'danger', '🔧');
600:         }
601:         v.speed = -v.speed * 0.22;
602:       } else {
603:         v.x = nx; v.y = ny;
604:       }
605:       v.x = clamp(v.x, 20, this.world.w * TILE - 20);
606:       v.y = clamp(v.y, 20, this.world.h * TILE - 20);
607:       this.player.x = v.x; this.player.y = v.y; this.player.angle = v.angle;
608:       // atropelamento
609:       if (Math.abs(v.speed) > 45) {
610:         for (const z of [...this.zombies]) {
611:           if (z.dead) continue;
612:           if (this.world.collidesRotRect(z.x, z.y, z.size * 12, v)) {
613:             this.damageZombie(z, 40 + Math.abs(v.speed) * 0.45, { angle: v.angle, head: false });
614:             v.condition = Math.max(0, v.condition - 0.8);
615:             v.speed *= 0.9;
616:             audio.play('car_hit');
617:             this.shake = Math.min(12, this.shake + 3);
618:           }
619:         }
620:         // atropelar NPCs hostis
621:         for (const n of [...this.npcs]) {
622:           if (!n.alive || !n.hostile) continue;
623:           if (this.world.collidesRotRect(n.x, n.y, 12, v)) this.damageNPC(n, 60, 'veiculo');
624:         }
625:       }
626:       // ruído do motor
627:       v.noiseTimer = (v.noiseTimer || 0) - dt;
628:       if (v.noiseTimer <= 0 && v.engineOn) {
629:         v.noiseTimer = 0.45;
630:         this.emitNoise(v.x, v.y, 560, 'veiculo');
631:       }
632:       // fumaça quando danificado
633:       if (v.condition < 35 && v.engineOn && chance(this.world.rng, dt * 8)) {
634:         this.addParticle({ x: v.x + Math.cos(v.angle) * 16, y: v.y + Math.sin(v.angle) * 16, vx: randRange(this.world.rng, -10, 10), vy: -18, life: 1.4, maxLife: 1.4, size: randRange(this.world.rng, 2, 5), color: '#555', gravity: -4, drag: 0.99 });
635:       }
636:       this.stats.distance += Math.abs(v.speed) * dt;
637:     }
638:   },
639: 
640:   enterVehicle(v) {
641:     const p = this.player;
642:     if (v.occupied) return;
643:     v.occupied = true;
644:     v.engineOn = v.fuel > 0 && v.condition > 0;
645:     p.inVehicle = v;
646:     this.completeObjective('vehicle');
647:     audio.play('car_start');
648:     this.emitNoise(v.x, v.y, 200, 'veiculo');
649:     this.ui?.notify(v.condition > 0 ? `${v.type} ligado. Combustível: ${Math.round(v.fuel)}%. Cuidado com o barulho.` : 'O veículo não liga.', v.condition > 0 ? 'good' : 'warn', '🚗');
650:     this.ui?.refreshHUD();
651:   },
652: 
653:   exitVehicle() {
654:     const p = this.player;
655:     const v = p.inVehicle;
656:     if (!v) return;
657:     v.occupied = false; v.engineOn = false; v.speed = 0;
658:     p.inVehicle = null;
659:     let placed = false;
660:     for (const a of [v.angle + Math.PI / 2, v.angle - Math.PI / 2, v.angle + Math.PI, v.angle]) {
661:       const x = v.x + Math.cos(a) * (v.h / 2 + 24);
662:       const y = v.y + Math.sin(a) * (v.h / 2 + 24);
