705:   // ================== NPCs ==================
706:   updateNPCs(dt) {
707:     const p = this.player;
708:     for (const n of [...this.npcs]) {
709:       if (!n.alive) continue;
710:       n.anim += dt;
711:       n.hitFlash = Math.max(0, n.hitFlash - dt * 3);
712:       n.attackCd = Math.max(0, n.attackCd - dt);
713:       n.alert = Math.max(0, (n.alert || 0) - dt);
714:       if (n.hostile) {
715:         const d = dist(n.x, n.y, p.x, p.y);
716:         if (d < 460 && !p.downed && this.world.lineOfSight(n.x, n.y, p.x, p.y)) { n.target = { x: p.x, y: p.y }; n.alert = 5; }
717:         if (n.alert > 0 && !p.downed) {
718:           if (n.weapon === 'pistola' && d > 80 && d < 430) {
719:             n.angle = angleTo(n.x, n.y, p.x, p.y);
720:             if (n.attackCd <= 0) {
721:               n.attackCd = randRange(this.world.rng, 1.2, 2.1);
722:               audio.play('gun');
723:               this.emitNoise(n.x, n.y, 750, 'tiro');
724:               this.addParticle({ x: n.x + Math.cos(n.angle) * 20, y: n.y + Math.sin(n.angle) * 20, vx: Math.cos(n.angle) * 60, vy: Math.sin(n.angle) * 60, life: 0.1, maxLife: 0.1, size: 8, color: '#ffd27a' });
725:               if (chance(this.world.rng, 0.68)) this.damagePlayer(randRange(this.world.rng, 8, 15), 'saqueador');
726:               this.addFloater(n.x, n.y - 30, 'SAQUEADOR', '#ff8c7a', 1);
727:             }
728:           } else if (d < 42) {
729:             if (n.attackCd <= 0) { n.attackCd = 1.1; this.damagePlayer(randRange(this.world.rng, 7, 13), 'saqueador'); }
730:           } else {
731:             this.npcMoveTo(n, p.x, p.y, n.speed, dt);
732:           }
733:         } else if (!n.wander || dist(n.x, n.y, n.wander.x, n.wander.y) < 20) {
734:           if (!n.wander || chance(this.world.rng, dt * 0.3)) n.wander = { x: n.home.x + randRange(this.world.rng, -180, 180), y: n.home.y + randRange(this.world.rng, -180, 180) };
735:           if (n.wander) this.npcMoveTo(n, n.wander.x, n.wander.y, n.speed * 0.4, dt);
736:         }
737:       } else {
738:         // aliado ou civil
739:         const z = this.nearestZombie(n.x, n.y, n.following ? 320 : 220);
740:         if (n.following && z && dist(n.x, n.y, z.x, z.y) < 240) {
741:           if (dist(n.x, n.y, z.x, z.y) < 38) {
742:             if (n.attackCd <= 0) {
743:               n.attackCd = 0.9;
744:               this.damageZombie(z, 20, { angle: angleTo(n.x, n.y, z.x, z.y) });
745:               audio.play('hit');
746:             }
747:           } else this.npcMoveTo(n, z.x, z.y, 130, dt);
748:         } else if (n.following) {
749:           const d = dist(n.x, n.y, p.x, p.y);
750:           if (d > 85) this.npcMoveTo(n, p.x, p.y, Math.min(150, 70 + d * 0.25), dt);
751:           else if (d < 45) { /* mantém distância */ }
752:           n.home = { x: p.x, y: p.y };
753:         } else {
754:           // civil: foge de zumbis próximos, senão vagueia
755:           const danger = this.nearestZombie(n.x, n.y, 200);
756:           if (danger && n.hp < 70) {
757:             const away = angleTo(danger.x, danger.y, n.x, n.y);
758:             this.moveEntity(n, Math.cos(away) * 110 * dt, Math.sin(away) * 110 * dt, 9);
759:             n.angle = away;
760:           } else {
761:             n.idleTimer -= dt;
762:             if (n.idleTimer <= 0) {
763:               n.idleTimer = randRange(this.world.rng, 2, 7);
764:               n.wander = chance(this.world.rng, 0.65) ? { x: n.home.x + randRange(this.world.rng, -160, 160), y: n.home.y + randRange(this.world.rng, -160, 160) } : null;
765:             }
766:             if (n.wander) {
767:               if (dist(n.x, n.y, n.wander.x, n.wander.y) < 18) n.wander = null;
768:               else this.npcMoveTo(n, n.wander.x, n.wander.y, n.speed, dt);
769:             }
770:           }
771:         }
772:       }
773:     }
