933:     if (bestGround) return { type: 'ground', label: `Pegar ${ITEMS[bestGround.stack.id]?.name || 'item'}`, ref: bestGround, key: 'E', icon: ITEMS[bestGround.stack.id]?.icon || '📦' };
934:     // NPC
