940:     }
941:     if (bestNpc) return { type: 'npc', label: `${bestNpc.following ? 'Falar com' : 'Conversar com'} ${bestNpc.name}`, ref: bestNpc, key: 'E', icon: '🧑' };
942:     // veículo
