960:         barricada: 'Desmontar barricada', reforco_metal: 'Desmontar reforço',
961:       };
962:       return { type: 'structure', ref: s, key: 'E', icon: s.type === 'fogueira' ? '🔥' : s.type === 'caixa' ? '📦' : s.type === 'canteiro' ? '🌱' : s.type === 'coletor' ? '🛢️' : '🧱', label: labels[s.type] || 'Usar estrutura' };
963:     }
