987: 
988:   nearestWater(x, y, radius = 60) {
989:     const tx = Math.floor(x / TILE), ty = Math.floor(y / TILE);
990:     let best = null, bd = radius;
991:     for (let yy = ty - 2; yy <= ty + 2; yy++) for (let xx = tx - 2; xx <= tx + 2; xx++) {
992:       if (this.world.tile(xx, yy) !== T.WATER) continue;
993:       const d = dist(x, y, xx * TILE + 16, yy * TILE + 16);
994:       if (d < bd) { bd = d; best = { x: xx, y: yy, dist: d }; }
995:     }
996:     return best;
997:   },
998: 
999:   interact() {
1000:     if (this.paused || this.dead) return;
1001:     const it = this.getInteractable();
1002:     if (!it) { this.ui?.notify('Nada por perto.', 'info', '•', 900); return; }
1003:     switch (it.type) {
1004:       case 'exit_vehicle': this.exitVehicle(); break;
1005:       case 'revive': this.reviveRemote(it.ref); break;
1006:       case 'ground': this.pickupGround(it.ref); break;
1007:       case 'npc': this.talkTo(it.ref); break;
1008:       case 'vehicle': this.enterVehicle(it.ref); break;
1009:       case 'container': this.openContainer(it.ref); break;
1010:       case 'structure': this.interactStructure(it.ref); break;
1011:       case 'door': this.toggleDoor(it.ref); break;
1012:       case 'bed': this.ui?.showSleepConfirm(); break;
1013:       case 'note': this.readNote(it.ref); break;
1014:       case 'window': this.breakWindow(it.ref); break;
1015:       case 'water': this.drinkWater(it.ref); break;
1016:       default: break;
1017:     }
1018:   },
